// Rigid abstract class hierarchy: single inheritance blocks mixins and evolution!
public abstract class Singer {
    abstract void sing();
}

public abstract class Songwriter {
    abstract void compose();
}

// Java DOES NOT allow extending multiple abstract classes!
// A SingerSongwriter cannot extend both Singer and Songwriter!
// public class SingerSongwriterImpl extends Singer, Songwriter { ... } // Compile error!
public class SingerSongwriterImpl extends Singer {
    @Override void sing() {}
    // Forced to duplicate or awkwardly simulate Songwriter functionality!
}

