right_code.class:
// Flexible interfaces with nonhierarchical composition and skeletal implementation
public interface Singer {
    void sing();
}

public interface Songwriter {
    void compose();
}

// Clean interface extension
public interface SingerSongwriter extends Singer, Songwriter {
    void strum();
    default void performLive() {
        compose();
        sing();
        strum();
    }
}

// Skeletal implementation pattern (combines interface flexibility with code reuse)
public class FolkArtist implements SingerSongwriter {
    @Override public void sing() { System.out.println("Singing a ballad..."); }
    @Override public void compose() { System.out.println("Composing acoustic tune..."); }
    @Override public void strum() { System.out.println("Strumming guitar..."); }
}

right_code.call_site:
public class Main {
    public static void main(String[] args) {
        SingerSongwriter artist = new FolkArtist();
        artist.performLive();
    }
}
